parameters.jsCode:
const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const d = item.json;
  const url = d.link || d.url || d.guid || '';
  if (!url || seen.has(url)) continue;
  seen.add(url);

  out.push({
    json: {
      title:       d.title       || d.jobTitle || 'Untitled',
      company:     d.creator     || d.author   || d.company || 'Unknown',
      location:    d.location    || d['dc:subject'] || 'Not specified',
      url:         url,
      description: d.contentSnippet || d.content || d.description || d.summary || '',
      source:      d['rss:source'] || (url.includes('linkedin') ? 'LinkedIn' : url.includes('naukri') ? 'Naukri' : url.includes('indeed') ? 'Indeed' : 'Other'),
      publishedAt: d.isoDate || d.pubDate || new Date().toISOString()
    }
  });
}

return out;

const seenRows = $('Load Seen URLs').all().map(r => r.json.url || '');
const seenSet  = new Set(seenRows);

return $('Deduplicate & Normalise')
  .all()
  .filter(item => !seenSet.has(item.json.url));

