parameters.jsCode:
const results = [];

for (const item of $input.all()) {
  const job = item.json;
  let ai;

  try {
    const raw = job.message?.content?.[0]?.text || job.text || '{}';
    const clean = raw.replace(/```json|```/g, '').trim();
    ai = JSON.parse(clean);
  } catch(e) {
    ai = { pass: false, fit_score: 0, top_reason: 'Parse error', flag: 'none', missing_keywords: [] };
  }

  if (!ai.pass || ai.fit_score < 6) continue;

  results.push({
    json: {
      title:            job.title,
      company:          job.company,
      location:         job.location,
      url:              job.url,
      source:           job.source,
      publishedAt:      job.publishedAt,
      fitScore:         ai.fit_score,
      seniority:        ai.seniority,
      topReason:        ai.top_reason,
      missingKeywords:  (ai.missing_keywords || []).join(', '),
      flag:             ai.flag,
      status:           'new',
      addedAt:          new Date().toISOString()
    }
  });
}

return results;
